"""build_table_aoe4.py — 从 AoE4 profile 生成快路径表(真产品那条线)

  python -m opencode_fastpath.build_table_aoe4
  产物: opencode_fastpath/table_aoe4.json
  来源: aoe4/profiles/aoe4-v1/{intent_config.aoe4.json, profile.json}
  闭集: profile.closed_set(补农一族) + triggers.aoe4_train_villager(一农..十农)
"""
from __future__ import annotations

import argparse
import json
from pathlib import Path

from .fastpath import FastPath
from .pinyin import Encoder

ROOT = Path(__file__).resolve().parent.parent
PROF = ROOT / "aoe4" / "profiles" / "aoe4-v1"
CN_NUM = {"一": 1, "二": 2, "三": 3, "四": 4, "五": 5,
          "六": 6, "七": 7, "八": 8, "九": 9, "十": 10}
DEFAULT_N = 3          # 裸「农」/「补农」= 补 3 个农民（联机默认）


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--profile-dir", default=str(PROF))
    ap.add_argument("--table", default=str(Path(__file__).resolve().parent / "table_aoe4.json"))
    a = ap.parse_args()
    pd = Path(a.profile_dir)
    cfg = json.loads((pd / "intent_config.aoe4.json").read_text(encoding="utf-8"))
    prof = json.loads((pd / "profile.json").read_text(encoding="utf-8"))
    intent = cfg["intents"][0]["id"]

    triggers = list(prof.get("closed_set") or [])            # 补农一族
    for t in cfg.get("triggers", {}).get(intent, []):        # 农 / 一农 .. 十农
        if t not in triggers:
            triggers.append(t)
    # 其它意图（如 vad_calibrate「调整静音判定」）的字面 triggers 也进表
    extra = []
    for it in cfg.get("intents", [])[1:]:
        for t in cfg.get("triggers", {}).get(it.get("id"), []):
            extra.append((it.get("id"), t))

    fp = FastPath(table_path=a.table, mode="off")
    fp.entries = []
    fp.enc = Encoder()
    for t in triggers:
        n = DEFAULT_N
        for ch, val in CN_NUM.items():
            if t.startswith(ch) and t.endswith("农"):
                n = val
                break
        fp.install(intent, n, [t], additive=True, markers={"source": "aoe4-profile"})
    for iid, t in extra:
        fp.install(iid, None, [t], additive=True, markers={"source": "aoe4-profile"})
    st = fp.stats()
    print(f"[OPENCODE] AoE4 表生成: 条目 {len(fp.entries)}  触发器 {len(triggers)}"
          f"  音节 {len(fp.enc.ids)}  行(全串/前缀) {st['full']}/{st['prefix']}  表体 {st['bytes']}B → {a.table}")
    for t in triggers[:6]:
        r = fp.route(t)
        print(f"   「{t}」 → {r['decision']} {r.get('intent') or ''} arg={r.get('arg')}")


if __name__ == "__main__":
    main()
